const fs = require('fs');
// Both runners read the SAME rubric + context pack from /scripts so the n8n
// chain and pipeline_qc.py cannot drift apart. context/ is NOT mounted into
// the container, which is why the doctrine + brand docs are shipped as
// context_pack.txt under scripts/ instead.
const pack   = fs.existsSync('/scripts/context_pack.txt')
  ? fs.readFileSync('/scripts/context_pack.txt','utf8') + '\n\n' : '';
const rubric = pack + fs.readFileSync('/scripts/rubric_stock.txt','utf8');
// Reference still of the persona, sent BEFORE the contact sheet. Without it
// a clip that is internally consistent but simply the wrong woman passes.
const reference_b64 = fs.readFileSync('/scripts/reference.jpg').toString('base64');
return [{ json: { rubric, reference_b64 } }];

const raw = $input.first().json.stdout || '[]';
let clips = [];
try { clips = JSON.parse(raw); } catch (e) { throw new Error('scan.py did not return JSON: ' + raw.slice(0,300)); }
if (!clips.length) return [];

// Everything below is interpolated into a shell command by the move nodes, and
// the model controls part of it (defects/note). Strip shell metacharacters and
// newlines so a reply like '"; rm -rf /data; #' cannot execute. Also caps the
// length so one rambling note cannot blow out the command line.
const shellSafe = (s) => String(s == null ? '' : s)
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/["'`$\\;&|<>]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 200) || 'no detail';

return clips.map(c => ({ json: {
  ...c,
  safe_reason: shellSafe((c.hard_fail_reasons || []).join('; ')),
} }));

// Runs once per item. Must stay in runOnceForEachItem mode: this body uses
// $json and $('Hard fail? (stock)').item, which are single-item constructs. In the
// default run-once-for-all-items mode it silently collapsed N Gemini replies
// into 1 and dropped every clip after the first.
const clip = $('Hard fail? (stock)').item.json;
let verdict = { verdict: 'review', confidence: 0, defects: [], note: 'unparseable model reply' };

// The Gemini node continues on error so one bad clip cannot strand the batch.
// A failed call arrives here as an error item; route it to review rather than
// silently rejecting a clip nobody actually looked at.
if ($json.error) {
  const msg = typeof $json.error === 'string' ? $json.error : ($json.error.message || JSON.stringify($json.error));
  // n8n wraps the upstream body as "400 - {json}"; pull out just the message
  // so the log line is readable instead of a mashed JSON blob.
  const m = String(msg).match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  verdict = { verdict: 'review', confidence: 0, defects: [], note: 'gemini call failed: ' + (m ? m[1] : String(msg)) };
} else {
  try {
    verdict = JSON.parse($json.candidates[0].content.parts[0].text);
  } catch (e) {}
}
if (!Array.isArray(verdict.defects)) verdict.defects = verdict.defects ? [String(verdict.defects)] : [];
if (typeof verdict.verdict !== 'string') verdict.verdict = 'review';
if (!['pass','review','fail'].includes(verdict.verdict)) verdict.verdict = 'review';

// Everything below is interpolated into a shell command by the move nodes, and
// the model controls part of it (defects/note). Strip shell metacharacters and
// newlines so a reply like '"; rm -rf /data; #' cannot execute. Also caps the
// length so one rambling note cannot blow out the command line.
const shellSafe = (s) => String(s == null ? '' : s)
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/["'`$\\;&|<>]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 200) || 'no detail';

const detail = verdict.defects.length ? verdict.defects.join('; ') : (verdict.note || '');
return { json: {
  ...clip,
  sheet_b64: undefined,
  ...verdict,
  safe_reason: shellSafe(verdict.verdict + ': ' + detail),
} };

